require_once __DIR__.'/includes/auth.php';require_login();require_once __DIR__.'/includes/olympia_store.php';olympia_ensure_schema();$weekId=trim((string)($_GET['week']??''));$classId=trim((string)($_GET['class']??''));$week=olympia_week($weekId);$class=olympia_class_map()[$classId]??[];if(!$week||!olympia_can_class($classId)||!in_array($classId,olympia_week_class_ids($weekId),true)){http_response_code(403);exit('Không có quyền mở màn hình trình chiếu này.');}$logo=BASE_URL.'assets/olympia-year-3.png';$yearDate=(string)($week['open_at']??date('Y-m-d'));$year=(int)substr($yearDate,0,4);$month=(int)substr($yearDate,5,2);if($month<7)$year--;$schoolYear=$year.' - '.($year+1);$footer='Cuộc thi ĐƯỜNG LÊN ĐỈNH OLYMPIA năm thứ 3 (Vòng sơ loại) - Trường PTDTNT THCS&THPT Xín Mần';
?><!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Màn hình Olympia</title><style>*{box-sizing:border-box}body{margin:0;background:#020716;color:#fff;font-family:Segoe UI,system-ui,sans-serif;overflow:hidden}.screen{height:100vh;display:flex;flex-direction:column;background:radial-gradient(circle at 50% 20%,#1476c5 0,#071b4d 48%,#020718 100%);position:relative}.screen:before,.screen:after{content:"✦  ✧  ✦  ✧  ✦";position:fixed;color:#fff7a8;font-size:clamp(18px,3vw,44px);letter-spacing:2.5vw;opacity:.65;animation:glitter 2.2s ease-in-out infinite;pointer-events:none}.screen:before{top:16%;left:5%}.screen:after{right:4%;bottom:18%;animation-delay:1.1s}header{height:11vh;display:flex;align-items:center;gap:18px;padding:10px 3vw;border-bottom:3px solid #ffd42a;background:#03143cdd}.logo{width:68px;height:68px;display:grid;place-items:center;overflow:hidden}.logo img{width:100%;height:100%;object-fit:contain}.title{font-size:clamp(22px,2.6vw,42px);font-weight:950}.class{margin-left:auto;text-align:right;font-size:clamp(18px,2vw,30px);color:#ffd42a;font-weight:800}main{flex:1;display:grid;place-items:center;padding:3vh 5vw 8vh}.welcome,.stage-intro,.waiting{text-align:center;position:relative;z-index:1}.event-logo{width:min(72vw,920px);max-height:46vh;object-fit:contain;filter:drop-shadow(0 0 28px #ffef63aa);animation:float 3s ease-in-out infinite}.welcome h1{font-size:clamp(30px,4.5vw,72px);margin:1vh 0;color:#fff;text-shadow:0 0 18px #71c9ff}.welcome h2{color:#ffe43b;font-size:clamp(22px,3vw,46px);margin:1vh}.stage-intro h1{font-size:clamp(32px,5vw,76px);margin:2vh}.stage-intro .stage-name{font-size:clamp(64px,10vw,160px);font-weight:950;color:#ffea32;text-shadow:0 0 32px #ffc400;letter-spacing:.06em}.stage{color:#ffd42a;text-transform:uppercase;letter-spacing:.18em;font-size:clamp(18px,2vw,32px);font-weight:900}.question{text-align:center;width:100%;max-width:1500px}.qtext{font-size:clamp(38px,5.2vw,86px);line-height:1.22;font-weight:900;margin:4vh auto}.answer{display:none;background:#06352e;border:2px solid #58e49e;border-radius:18px;padding:2vh 3vw;font-size:clamp(28px,3.8vw,62px);color:#baffd5}.timer{width:120px;height:120px;border:8px solid #ffd42a;border-radius:50%;display:grid;place-items:center;margin:3vh auto;font-size:44px;font-weight:950}.summary{text-align:center}.summary h1{font-size:clamp(44px,7vw,110px);margin:2vh}.big{font-size:clamp(70px,13vw,210px);font-weight:950;color:#ffd42a}.event-footer{position:fixed;left:0;right:0;bottom:0;padding:12px 3vw;background:#020b28ee;border-top:2px solid #e4c82b;text-align:center;font-weight:750;font-size:clamp(13px,1.45vw,22px);z-index:4}.connection{position:fixed;right:12px;top:12px;opacity:.55;font-size:12px;z-index:5}.paused{font-size:clamp(50px,9vw,140px);font-weight:950;color:#ffe532;text-shadow:0 0 30px #ffcf00}.pulse{animation:pulse 1.5s infinite}@keyframes pulse{50%{transform:scale(1.06);opacity:.75}}@keyframes glitter{50%{opacity:.15;transform:scale(.85)}}@keyframes float{50%{transform:translateY(-10px)}}</style></head><body><div class="screen"><header><div class="logo"><img src="<?=e($logo)?>" alt="Logo"></div><div><div class="title">ĐƯỜNG LÊN ĐỈNH OLYMPIA</div><div><?=e($week['title'])?> · Năm học <?=e($schoolYear)?></div></div><div class="class">LỚP <?=e($class['name']??'')?></div></header><main id="main"></main><div class="connection" id="connection">Đang kết nối…</div><footer class="event-footer"><?=e($footer)?></footer></div><script>
const endpoint='<?=BASE_URL?>hoclieu_game_olympia_live.php?week=<?=rawurlencode($weekId)?>&class=<?=rawurlencode($classId)?>',eventLogo='<?=e($logo)?>',weekTitle=<?=json_encode((string)$week['title'],JSON_UNESCAPED_UNICODE)?>,schoolYear=<?=json_encode($schoolYear)?>;let last='',timer=null;const main=document.getElementById('main'),conn=document.getElementById('connection');function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function welcome(){main.innerHTML=`<div class="welcome"><h1>CHÀO MỪNG CÁC BẠN ĐẾN VỚI CUỘC THI</h1><img class="event-logo" src="${eventLogo}" alt="Olympia"><h2>${esc(weekTitle)} · NĂM HỌC ${esc(schoolYear)}</h2></div>`}function draw(s){let key=JSON.stringify(s);if(key===last)return;last=key;clearInterval(timer);if(!s||['waiting','intro','welcome'].includes(s.status)){welcome();return}if(s.status==='stage_intro'){main.innerHTML=`<div class="stage-intro"><img class="event-logo" src="${eventLogo}" alt="Olympia"><h1>PHẦN THI</h1><div class="stage-name">${esc(s.stage)}</div><h2>NĂM HỌC ${esc(schoolYear)}</h2></div>`;return}if(s.status==='paused'){main.innerHTML=`<div class="stage-intro"><img class="event-logo" src="${eventLogo}" alt="Olympia"><div class="paused">TẠM DỪNG</div><h2>CUỘC THI SẼ TIẾP TỤC TRONG ÍT PHÚT</h2></div>`;return}if(s.status==='stage_summary'||s.status==='finished'){main.innerHTML=`<div class="summary"><div class="stage">${esc(s.stage||'Kết quả')}</div><h1>${s.status==='finished'?'CUỘC THI ĐÃ KẾT THÚC':'HOÀN THÀNH PHẦN THI'}</h1><div class="big">${Number(s.stage_score||s.total_score||0)}</div><p>ĐIỂM</p></div>`;return}if(s.status==='score_result'){let names=Array.isArray(s.awarded_students)&&s.awarded_students.length?s.awarded_students.map(esc).join(', '):'Không có học sinh ghi điểm';main.innerHTML=`<div class="summary"><div class="stage">KẾT QUẢ CÂU HỎI</div><h1>${names}</h1><div class="big">+${Number(s.question_score||0)}</div><p>TỔNG ĐIỂM LỚP: ${Number(s.total_score||0)}</p></div>`;return}main.innerHTML=`<div class="question"><div class="stage">${esc(s.stage)} · ${Number(s.points||0)} ĐIỂM</div><div class="qtext">${esc(s.question)}</div><div class="timer" id="clock">${Number(s.seconds||0)}</div><div class="answer" id="ans">ĐÁP ÁN: ${esc(s.answer)}</div></div>`;if(s.status==='answer')document.getElementById('ans').style.display='block';if(s.timer_ends_at){let tick=()=>{let left=Math.max(0,Math.ceil((Number(s.timer_ends_at)-Date.now())/1000)),el=document.getElementById('clock');if(el)el.textContent=left||'HẾT'};tick();timer=setInterval(tick,250)}}async function poll(){try{let r=await fetch(endpoint,{cache:'no-store'}),d=await r.json();if(d.ok){draw(d.state);conn.textContent='Đồng bộ · '+(d.controlled_by||'Giáo viên')}else conn.textContent=d.message}catch(e){conn.textContent='Mất kết nối, đang thử lại…'}}welcome();poll();setInterval(poll,900);
</script></body></html>
